```javascript
function decodeHexPacket(hex) {
  if (typeof hex !== 'string') {
    throw new TypeError('hex must be a string');
  }
  if (hex.length === 0 || hex.length % 2 !== 0 || !/^[0-9a-f]+$/i.test(hex)) {
    throw new Error('malformed hexadecimal packet');
  }

  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i += 1) {
    bytes[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }

  const payloadLength = bytes[0];
  if (bytes.length !== payloadLength + 2) {
    throw new Error('packet length mismatch');
  }

  let checksum = 0;
  for (let i = 0; i < bytes.length - 1; i += 1) {
    checksum = (checksum + bytes[i]) & 0xff;
  }
  if (checksum !== bytes[bytes.length - 1]) {
    throw new Error('checksum mismatch');
  }

  return bytes.slice(1, bytes.length - 1);
}

module.exports = { decodeHexPacket };
```

